# migration files to aerich rows.
from tortoise import BaseDBAsyncClient

RUN_IN_TRANSACTION = True


async def upgrade(db: BaseDBAsyncClient) -> str:
    return """
        CREATE TABLE IF NOT EXISTS "return_90_post" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
    "channel_id" BIGINT,
    "message_id" BIGINT,
    "staff_channel_id" BIGINT,
    "ping_role_id" BIGINT,
    "shown_kind" VARCHAR(16) NOT NULL DEFAULT 'card',
    "shown_id" INT,
    "shown_epoch" INT NOT NULL DEFAULT 0,
    "frozen" INT NOT NULL DEFAULT 0,
    "ended" INT NOT NULL DEFAULT 0,
    "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) /* Singleton (``id`` is always 1): the announcement message and what dazebot */;"""


async def downgrade(db: BaseDBAsyncClient) -> str:
    return """
        DROP TABLE IF EXISTS "return_90_post";"""


